<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { ArrowLeft, Copy, LogOut, Plus, Users } from 'lucide-vue-next'
import { isSupabaseConfigured, requireSupabase } from '../services/supabase'
type Difficulty='beginner'|'intermediate'|'advanced'|'mixed'
type SessionRow={id:string;code:string;title:string;mode:'self_paced'|'live';status:string;created_at:string;current_question_index:number;question_count:number;difficulty:Difficulty;activity_type?:'assessment'|'adventure';adventure_game_id?:string|null}
type AnswerDetail={position:number;prompt:string;selected_answer:string;correct_answer:string;explanation:string;is_correct:boolean}
type Participant={id:string;nickname:string;score:number;joined_at:string;finished_at:string|null;correct:number;incorrect:number;answers:AnswerDetail[]}
const AUTHORIZED_TEACHER_EMAIL='juanisidromejia@gmail.com'
const email=ref(AUTHORIZED_TEACHER_EMAIL),loggedIn=ref(false),busy=ref(false),message=ref('')
const sessions=ref<SessionRow[]>([]),selectedSession=ref<SessionRow|null>(null),participants=ref<Participant[]>([])
const title=ref('Prueba de guitarra'),activityType=ref<'assessment'|'adventure'>('assessment'),mode=ref<'self_paced'|'live'>('self_paced'),questionCount=ref(12),difficulty=ref<Difficulty>('beginner')
const nextFeedback=ref(false)
let nextFeedbackTimer:ReturnType<typeof setTimeout>|undefined
let channel:any=null
const shareUrl=computed(()=>selectedSession.value?`${window.location.origin}/sesion/${selectedSession.value.code}`:'')
function difficultyLabel(value:Difficulty){return ({beginner:'Principiante',intermediate:'Intermedio',advanced:'Avanzado',mixed:'Mixto'} as const)[value]}
async function sendLogin(){busy.value=true;message.value='';try{if(email.value.trim().toLowerCase()!==AUTHORIZED_TEACHER_EMAIL){throw new Error('El acceso docente está reservado al correo autorizado.')}const {error}=await requireSupabase().auth.signInWithOtp({email:AUTHORIZED_TEACHER_EMAIL,options:{emailRedirectTo:window.location.origin+'/docente/sesiones',shouldCreateUser:false}});if(error)throw error;message.value='Te enviamos un enlace de acceso. Abre el mensaje más reciente en este mismo navegador.'}catch(e){message.value=e instanceof Error?e.message:'No se pudo iniciar sesión.'}finally{busy.value=false}}
async function loadSessions(){const {data,error}=await requireSupabase().from('sessions').select('id,code,title,mode,status,created_at,current_question_index,question_count,difficulty,activity_type,adventure_game_id').order('created_at',{ascending:false});if(error)throw error;sessions.value=data as SessionRow[]}
async function refreshParticipants(){if(!selectedSession.value)return;const db=requireSupabase();const sid=selectedSession.value.id;const [pr,rr]=await Promise.all([db.from('participants').select('id,nickname,score,joined_at,finished_at').eq('session_id',sid).order('score',{ascending:false}),db.rpc('get_class_session_results',{p_session_id:sid})]);if(pr.error)throw pr.error;if(rr.error)throw rr.error;const details=(rr.data??[]) as {participant_id:string;answers:AnswerDetail[]}[];participants.value=(pr.data??[]).map(p=>{const answers=details.find(x=>x.participant_id===p.id)?.answers??[];return {...p,answers,correct:answers.filter(a=>a.is_correct).length,incorrect:answers.filter(a=>!a.is_correct).length}}) as Participant[]}
async function createSession(){busy.value=true;message.value='';try{const {data,error}=activityType.value==='adventure'?await requireSupabase().rpc('create_class_adventure_session',{p_title:title.value.trim()||'Aventura musical',p_difficulty:difficulty.value}):await requireSupabase().rpc('create_class_session',{p_title:title.value.trim()||'Sesión de evaluación',p_mode:mode.value,p_question_count:questionCount.value,p_difficulty:difficulty.value});if(error)throw error;await loadSessions();selectedSession.value=data as SessionRow;await refreshParticipants();subscribe();message.value=activityType.value==='adventure'?'Bonus preparado. Comparte el mismo código de sesión con tus estudiantes.':'Sesión creada. Comparte el enlace o el código con tus estudiantes.'}catch(e){message.value=e instanceof Error?e.message:(e&&typeof e==='object'&&'message' in e?String(e.message):'No se pudo crear la sesión.');console.error('Error al crear sesión:',e)}finally{busy.value=false}}
async function selectSession(s:SessionRow){selectedSession.value=s;try{await refreshParticipants();subscribe()}catch(e){message.value=e instanceof Error?e.message:'Error al cargar participantes.'}}
function subscribe(){if(channel)requireSupabase().removeChannel(channel);if(!selectedSession.value)return;const sid=selectedSession.value.id;channel=requireSupabase().channel('teacher-'+sid).on('postgres_changes',{event:'*',schema:'public',table:'participants',filter:'session_id=eq.'+sid},()=>refreshParticipants()).on('postgres_changes',{event:'*',schema:'public',table:'sessions',filter:'id=eq.'+sid},async payload=>{if(selectedSession.value)selectedSession.value={...selectedSession.value,...payload.new as Partial<SessionRow>};await loadSessions()}).subscribe()}
async function control(action:'start'|'next'|'finish'){if(!selectedSession.value)return;const fn=action==='start'?'start_class_session':action==='next'?'advance_class_session':'finish_class_session';const {error}=await requireSupabase().rpc(fn,{p_session_id:selectedSession.value.id});if(error){message.value=error.message;return}await loadSessions();const latest=sessions.value.find(s=>s.id===selectedSession.value?.id);if(latest)selectedSession.value=latest;await refreshParticipants();if(action==='next'&&selectedSession.value.status==='active'){message.value=`Ahora está abierta la pregunta ${selectedSession.value.current_question_index+1} de ${selectedSession.value.question_count}.`;nextFeedback.value=true;if(nextFeedbackTimer)clearTimeout(nextFeedbackTimer);nextFeedbackTimer=setTimeout(()=>{nextFeedback.value=false},700)}else if(action==='start')message.value='La sesión está en marcha. Pregunta 1 abierta.';else if(action==='finish')message.value='La sesión ha finalizado.'}
async function copy(value:string){try{await navigator.clipboard.writeText(value);message.value='Copiado al portapapeles.'}catch{message.value=value}}
async function logout(){await requireSupabase().auth.signOut();loggedIn.value=false;sessions.value=[];selectedSession.value=null;participants.value=[]}
onMounted(async()=>{if(!isSupabaseConfigured)return;const db=requireSupabase();const isAllowed=(s:any)=>Boolean(s&&!s.user.is_anonymous&&s.user.email?.toLowerCase()===AUTHORIZED_TEACHER_EMAIL);const {data}=await db.auth.getSession();loggedIn.value=isAllowed(data.session);if(data.session&&!data.session.user.is_anonymous&&!isAllowed(data.session)){message.value='Esta cuenta no tiene autorización para administrar sesiones.';await db.auth.signOut()}if(loggedIn.value)try{await loadSessions()}catch(e){message.value=e instanceof Error?e.message:'Error al cargar sesiones.'}db.auth.onAuthStateChange((_event,s)=>{loggedIn.value=isAllowed(s);if(loggedIn.value)loadSessions().catch(e=>message.value=e.message);else if(s&&!s.user.is_anonymous)void db.auth.signOut()})})
onUnmounted(()=>{if(channel)requireSupabase().removeChannel(channel);if(nextFeedbackTimer)clearTimeout(nextFeedbackTimer)})
</script>
<template>
<div class="page">
 <div class="mb-6 flex items-center gap-3"><RouterLink to="/" class="secondary"><ArrowLeft :size="17"/></RouterLink><div><p class="eyebrow">Herramientas docentes</p><h1 class="text-2xl font-black sm:text-3xl">Sesiones de evaluación</h1></div></div>
 <section v-if="!isSupabaseConfigured" class="panel p-6"><h2 class="text-xl font-black">Falta conectar Supabase</h2><p class="mt-2 text-sm leading-6 text-[#687970]">La interfaz está preparada. Configura el proyecto Supabase y las variables de entorno siguiendo <code>supabase/README.md</code> y <code>.env.example</code>.</p></section>
 <section v-else-if="!loggedIn" class="panel mx-auto max-w-xl p-6 sm:p-8"><div class="grid h-12 w-12 place-items-center rounded-2xl bg-[#e8f2eb] text-[#26745a]"><Users/></div><h2 class="mt-4 text-xl font-black">Acceso docente</h2><p class="mt-2 text-sm text-[#718078]">El acceso está reservado temporalmente a <b>juanisidromejia@gmail.com</b>. Recibirás un enlace seguro en ese correo.</p><form class="mt-5 space-y-3" @submit.prevent="sendLogin"><label class="block text-sm font-bold">Correo electrónico</label><input v-model="email" type="email" required readonly autocomplete="email" class="w-full rounded-xl border border-[#dce6dd] bg-[#f5f8f5] px-4 py-3"/><button class="primary w-full justify-center" :disabled="busy">{{busy?'Enviando…':'Enviar enlace de acceso'}}</button></form><p v-if="message" class="mt-3 text-sm text-[#37644f]">{{message}}</p></section>
 <template v-else>
  <div class="mb-4 flex justify-end"><button class="secondary inline-flex items-center gap-2" @click="logout"><LogOut :size="16"/> Cerrar sesión</button></div>
  <div class="grid gap-4 lg:grid-cols-[.85fr_1.15fr]">
   <section class="panel p-5 sm:p-6"><h2 class="text-lg font-black">Crear una sesión</h2><p class="mt-1 text-sm text-[#718078]">Banco ampliado: 60 preguntas organizadas por nivel y área musical.</p><form class="mt-5 space-y-4" @submit.prevent="createSession">
    <div><label class="mb-1 block text-sm font-bold">Nombre de la sesión</label><input v-model="title" required maxlength="90" class="w-full rounded-xl border border-[#dce6dd] px-3 py-3"/></div>
    <div><label class="mb-2 block text-sm font-bold">Actividad</label><label class="mb-2 flex cursor-pointer gap-3 rounded-xl border p-3" :class="activityType==='assessment'?'border-[#398568] bg-[#f0f7f1]':'border-[#e2e9e3]'"><input v-model="activityType" type="radio" value="assessment" class="mt-1 accent-[#26745a]"/><span><b class="block text-sm">Evaluación habitual</b><small class="text-[#718078]">Preguntas y respuestas online.</small></span></label><label class="flex cursor-pointer gap-3 rounded-xl border p-3" :class="activityType==='adventure'?'border-[#398568] bg-[#f0f7f1]':'border-[#e2e9e3]'"><input v-model="activityType" type="radio" value="adventure" class="mt-1 accent-[#26745a]"/><span><b class="block text-sm">Bonus sorpresa · Catacumbas</b><small class="text-[#718078]">El mismo código abrirá una aventura en lugar de la prueba.</small></span></label></div>
    <div v-if="activityType==='assessment'"><label class="mb-1 block text-sm font-bold">Número de preguntas</label><select v-model.number="questionCount" class="w-full rounded-xl border border-[#dce6dd] bg-white px-3 py-3"><option :value="5">5 preguntas</option><option :value="8">8 preguntas</option><option :value="10">10 preguntas</option><option :value="12">12 preguntas</option><option :value="15">15 preguntas</option><option :value="20">20 preguntas</option></select><p class="mt-1 text-xs text-[#718078]">Se elegirán al azar sin repetir dentro de esta sesión.</p></div>
    <div><label class="mb-1 block text-sm font-bold">Nivel de dificultad</label><select v-model="difficulty" class="w-full rounded-xl border border-[#dce6dd] bg-white px-3 py-3"><option value="beginner">Principiante</option><option value="intermediate">Intermedio</option><option value="advanced">Avanzado</option><option value="mixed">Mixto · los tres niveles</option></select><p class="mt-1 text-xs text-[#718078]">En nivel mixto, las preguntas se distribuyen entre los tres niveles.</p></div>
    <div v-if="activityType==='assessment'"><label class="mb-2 block text-sm font-bold">Modalidad</label><label class="mb-2 flex cursor-pointer gap-3 rounded-xl border p-3" :class="mode==='self_paced'?'border-[#398568] bg-[#f0f7f1]':'border-[#e2e9e3]'"><input v-model="mode" type="radio" value="self_paced" class="mt-1 accent-[#26745a]"/><span><b class="block text-sm">Cada estudiante a su ritmo</b><small class="text-[#718078]">Cada participante responde de forma independiente.</small></span></label><label class="flex cursor-pointer gap-3 rounded-xl border p-3" :class="mode==='live'?'border-[#398568] bg-[#f0f7f1]':'border-[#e2e9e3]'"><input v-model="mode" type="radio" value="live" class="mt-1 accent-[#26745a]"/><span><b class="block text-sm">En vivo, dirigida por el docente</b><small class="text-[#718078]">El docente abre cada pregunta para todos.</small></span></label></div>
    <button class="primary w-full justify-center" :disabled="busy"><Plus :size="17"/>{{busy?'Creando…':'Crear sesión'}}</button></form><p v-if="message" class="mt-3 rounded-xl bg-[#f0f5f0] p-3 text-sm text-[#37644f]">{{message}}</p></section>
   <section class="panel p-5 sm:p-6"><h2 class="text-lg font-black">Tus sesiones</h2><p v-if="!sessions.length" class="mt-3 text-sm text-[#718078]">Todavía no has creado sesiones.</p><div v-else class="mt-3 space-y-2"><button v-for="s in sessions" :key="s.id" class="flex w-full items-center justify-between rounded-xl border p-3 text-left hover:bg-[#f5f8f5]" :class="selectedSession?.id===s.id?'border-[#398568] bg-[#f0f7f1]':'border-[#e4ebe5]'" @click="selectSession(s)"><span class="min-w-0"><b class="block truncate text-sm">{{s.title}}</b><small class="text-[#718078]">{{s.code}} · {{s.activity_type==='adventure'?'Bonus sorpresa':'Evaluación'}} · {{difficultyLabel(s.difficulty)}}</small></span><span class="rounded-full bg-[#edf4ee] px-2 py-1 text-xs font-bold">{{s.status}}</span></button></div>
    <div v-if="selectedSession" class="mt-5 border-t border-[#e8eee8] pt-4"><div class="flex flex-wrap items-center justify-between gap-2"><div><h3 class="font-extrabold">Compartir con estudiantes</h3><p class="mt-1 text-xs text-[#718078]">{{difficultyLabel(selectedSession.difficulty)}} · {{selectedSession.activity_type==='adventure'?'Aventura bonus':' '+selectedSession.question_count+' preguntas'}}</p></div><span class="text-xs text-[#718078]">Código: <b>{{selectedSession.code}}</b></span></div><RouterLink v-if="selectedSession.activity_type==='adventure'&&selectedSession.adventure_game_id" class="primary mt-3" :to="{path:'/aventura',query:{role:'teacher',gameId:selectedSession.adventure_game_id,sessionId:selectedSession.id}}">Abrir panel de aventura</RouterLink>
     <div class="mt-3 flex gap-2"><input readonly :value="shareUrl" class="min-w-0 flex-1 rounded-xl border border-[#dce6dd] bg-[#f8faf8] px-3 py-2 text-xs"/><button class="secondary" title="Copiar enlace" @click="copy(shareUrl)"><Copy :size="16"/></button></div><button class="mt-2 text-sm font-bold text-[#26745a]" @click="copy(selectedSession.code)">Copiar código manual</button>
     <div v-if="selectedSession.mode==='live'&&selectedSession.status==='active'" class="mt-4 rounded-xl bg-[#edf4ee] px-4 py-3 text-sm font-bold text-[#28684f] transition-all duration-200" :class="nextFeedback?'bg-[#dceee2] ring-2 ring-[#8dbda0]':''" aria-live="polite">Pregunta {{selectedSession.current_question_index+1}} de {{selectedSession.question_count}} en pantalla</div>
     <div class="mt-5 flex flex-wrap gap-2" v-if="selectedSession.status!=='finished'"><button v-if="selectedSession.status==='lobby'" class="primary" @click="control('start')">{{selectedSession.activity_type==='adventure'?'Iniciar aventura':selectedSession.mode==='live'?'Iniciar sesión':'Abrir prueba'}}</button><template v-else-if="selectedSession.mode==='live'&&selectedSession.activity_type!=='adventure'"><button class="primary transition-all duration-100 ease-out active:translate-y-px active:scale-[0.97] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#398568]" :class="nextFeedback?'scale-[1.02] brightness-110 ring-2 ring-[#398568]':''" @click="control('next')">Siguiente pregunta</button><button class="secondary" @click="control('finish')">Finalizar sesión</button></template><button v-else-if="selectedSession.activity_type==='adventure'" class="secondary" @click="control('finish')">Finalizar aventura</button><button v-else class="secondary" @click="control('finish')">Cerrar prueba</button></div>
     <div class="mt-5 flex items-center justify-between"><h3 class="font-extrabold">Resultados del grupo</h3><span class="text-xs text-[#718078]">{{participants.length}} participantes</span></div><p v-if="!participants.length" class="mt-3 rounded-xl bg-[#f5f8f5] p-4 text-sm text-[#718078]">Aún no han ingresado estudiantes.</p><div v-else class="mt-3 space-y-2"><div v-for="(p,i) in participants" :key="p.id" class="rounded-xl bg-[#f5f8f5] p-3"><div class="flex items-center justify-between gap-2"><span class="text-sm font-bold">{{i+1}}. {{p.nickname}} <small v-if="p.finished_at" class="font-normal text-[#398568]">· finalizó</small></span><b class="text-sm tabular-nums">{{p.score}} pts</b></div><p class="mt-1 text-xs text-[#718078]">{{p.correct}} correctas · {{p.incorrect}} incorrectas</p><details v-if="p.answers.length" class="mt-3 border-t border-[#e0e9e1] pt-2"><summary class="cursor-pointer text-xs font-bold text-[#28684f]">Ver respuestas y errores ({{p.answers.length}})</summary><div class="mt-3 space-y-3"><div v-for="a in p.answers" :key="a.position" class="rounded-lg bg-white p-3"><p class="text-xs font-bold">Pregunta {{a.position+1}} · {{a.is_correct?'Correcta':'Incorrecta'}}</p><p class="mt-1 text-sm">{{a.prompt}}</p><p class="mt-2 text-xs text-[#718078]">Respondió: <b class="text-[#34483d]">{{a.selected_answer}}</b></p><p v-if="!a.is_correct" class="mt-1 text-xs text-[#26745a]">Respuesta correcta: <b>{{a.correct_answer}}</b></p><p v-if="!a.is_correct&&a.explanation" class="mt-1 text-xs text-[#718078]">{{a.explanation}}</p></div></div></details></div></div>
    </div>
   </section>
  </div>
 </template>
</div>
</template>
